const prepare = function prepareTestimonial(inputs) {
  const fields = inputs.body?.data?.fields;
  if (!Array.isArray(fields)) throw new Error('Expected data.fields with author first and feedback second.');
  const Author = fields[0]?.value;
  const Content = fields[1]?.value;
  if (typeof Author !== 'string' || !Author.trim() || typeof Content !== 'string' || !Content.trim()) throw new Error('Author and feedback must be nonempty text fields.');
  const Created = new Date().toISOString();
  return { Author, Content, Created, URL: '', request: { document: { type: 'PLAIN_TEXT', content: Content }, encodingType: 'UTF16' } };
}

return [{json:prepare({body:$input.first().json.body}),pairedItem:{item:0}}];

const validate = function readSentiment(inputs) {
  const body = inputs.body;
  const score = body?.documentSentiment?.score;
  if (!body || typeof body !== 'object' || Array.isArray(body) || body.error || typeof score !== 'number' || !Number.isFinite(score) || score < -1 || score > 1) throw new Error('The sentiment service did not return a valid document score.');
  return { score };
}

return [{json:validate({body:$input.first().json}),pairedItem:{item:0}}];

const payload = function prepareStrapiPayload(inputs) {
  const { Author, Content, Created, URL } = inputs;
  return { record: { Content, Author, Created, URL }, body: { data: { Content, Author, Created, URL } } };
}

return [{json:payload($('Read Author and Feedback').first().json).record,pairedItem:{item:0}}];

const pack = function testimonialResult(inputs) {
  if (inputs.body === null) return { result: { status: 'ignored', score: inputs.score, entry: null } };
  const body = inputs.body;
  const entry = body?.data;
  if (!body || typeof body !== 'object' || body.error || !entry || typeof entry !== 'object' || Array.isArray(entry) || !(typeof entry.documentId === 'string' && entry.documentId || typeof entry.id === 'number' && Number.isFinite(entry.id) || typeof entry.id === 'string' && entry.id)) throw new Error('Strapi did not confirm a created entry.');
  return { result: { status: 'captured', score: inputs.score, entry } };
}

return [{json:pack({body:$input.first().json,score:$('Validate Form Score').first().json.score}).result,pairedItem:{item:0}}];

